<script lang="ts">
  import { onMount } from 'svelte';
  import CanonicalLayout from './CanonicalLayout.svelte';
  import { canonicalLayoutRoots,type CanonicalKind,type CanonicalTypeDefinition,type CanonicalTypeSettings } from '$lib/contracts/canonicalTypes';
  let {projectId,kind,onDirtyChange,onBusyChange}:{projectId:string;kind:CanonicalKind;onDirtyChange:(value:boolean)=>void;onBusyChange:(value:boolean)=>void}=$props();
  let fields=$state('{}'),defaults=$state('{}'),migrateDefaults=$state(false);
  let saved=$state<CanonicalTypeSettings|null>(null),layout=$state('[]'),context=$state('searchable'),baseline=$state(''),busy=$state(false),message=$state('');
  let preview=$state<CanonicalTypeDefinition|null>(null),impact=$state<{total:number;inherited:number;pinned:number;partial:number;estimatedTokens:number}|null>(null),confirmation=$state<{definition:CanonicalTypeDefinition;expectedRevision:number;expectedSnapshot:string;migrateDefaults:boolean;migrationCount:number}|null>(null);
  let revisions=$state<Array<{revision:number;definition:CanonicalTypeDefinition;reason:string}>>([]),older=$state<number|null>(null);
  let restoreReview=$state<{targetRevision:number;expectedSnapshot:string;compatible:boolean;conflicts:{name:string;error:string}[];changes:{field:string;from:unknown;to:unknown}[];migrationCount:number;revision:number}|null>(null),restoreMigrate=$state(false);
  const snapshot=()=>JSON.stringify({layout,context,fields,defaults,migrateDefaults});const dirty=$derived(!!saved && baseline!==snapshot());
  $effect(()=>onDirtyChange(dirty||busy));$effect(()=>onBusyChange(busy));
  $effect(()=>{if(confirmation && JSON.stringify({layout:JSON.stringify(confirmation.definition.layout,null,2),context:confirmation.definition.gmContextMode,fields:JSON.stringify(confirmation.definition.fields??{},null,2),defaults:JSON.stringify(confirmation.definition.defaults??{},null,2),migrateDefaults:confirmation.migrateDefaults})!==snapshot())confirmation=null;});
  const sample=$derived({name:'Example '+kind,description:'An example description',state:{bio:'Example biography',stats:{hp:12,ac:16}},goals:['An example goal'],resources:{gold:20},pressure:0,status:'active',visibility:'player_known',metadata:{contentFields:preview?.defaults??{}}});
  async function call(command:string,args:Record<string,unknown>={}){const response=await fetch('/api/engine/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({storyId:'__app__',command:'content.canonicalTypes.'+command,args:{projectId,kind,...args}})});const body=await response.json();if(!response.ok||body.status!=='succeeded')throw new Error(body.error??'Type request failed.');return body.result;}
  async function act(fn:()=>Promise<void>){busy=true;message='';try{await fn();}catch(error){message=String(error);}finally{busy=false;}}
  function accept(value:CanonicalTypeSettings){saved=value;fields=JSON.stringify(value.definition.fields??{},null,2);defaults=JSON.stringify(value.definition.defaults??{},null,2);migrateDefaults=false;layout=JSON.stringify(value.definition.layout,null,2);context=value.definition.gmContextMode;baseline=snapshot();preview=value.definition;confirmation=null;revisions=[];older=null;restoreReview=null;}
  async function reload(){await act(async()=>accept(await call('read')));}
  onMount(()=>{void reload();return()=>{onDirtyChange(false);onBusyChange(false);};});
  async function save(previewOnly=false){if(!saved)return;await act(async()=>{
    const definition={layout:JSON.parse(layout),gmContextMode:context,fields:JSON.parse(fields),defaults:JSON.parse(defaults)};
    const checked=await call('preview',{expectedRevision:saved!.revision,definition,migrateDefaults});preview=checked.definition;impact=checked.impact;
    if(!checked.compatible)throw new Error(checked.conflicts.map((r:{name:string;error:string})=>r.name+': '+r.error).join('\n'));
    if(previewOnly){message='Schema and layout are valid. '+checked.migrationCount+' records would receive missing defaults. Preview uses sample values.';return;}
    if(checked.requiresClearConfirmation||checked.migrationCount>0){fields=JSON.stringify(checked.definition.fields??{},null,2);defaults=JSON.stringify(checked.definition.defaults??{},null,2);layout=JSON.stringify(checked.definition.layout,null,2);confirmation={definition:checked.definition,expectedRevision:saved!.revision,expectedSnapshot:checked.expectedSnapshot,migrateDefaults,migrationCount:checked.migrationCount};return;}
    accept(await call('save',{expectedRevision:saved!.revision,definition:checked.definition,migrateDefaults,expectedSnapshot:checked.expectedSnapshot}));message='Built-in type settings saved.';
  });}
  async function history(more=false){await act(async()=>{const result=await call('history',{limit:20,...(more&&older!==null?{beforeRevision:older}:{})});revisions=more?[...revisions,...result.revisions]:result.revisions;older=result.nextBeforeRevision;restoreReview=null;});}
  async function previewRestore(targetRevision:number){if(!saved)return;await act(async()=>{restoreReview=await call('previewRestore',{targetRevision,expectedRevision:saved!.revision,migrateDefaults:restoreMigrate});});}
  async function applyRestore(){if(!saved||!restoreReview||!restoreReview.compatible||dirty||busy)return;const reviewed=restoreReview;await act(async()=>{accept(await call('restore',{targetRevision:reviewed.targetRevision,expectedRevision:reviewed.revision,expectedSnapshot:reviewed.expectedSnapshot,confirmed:true,migrateDefaults:restoreMigrate}));message='Historical built-in type restored as a new revision.';});}
  async function confirmClear(){if(!confirmation)return;const approved=confirmation;await act(async()=>{accept(await call('save',{definition:approved.definition,expectedRevision:approved.expectedRevision,expectedSnapshot:approved.expectedSnapshot,migrateDefaults:approved.migrateDefaults,confirmedClear:true}));message='Reviewed type changes applied; history retained.';});}
</script>
<section aria-label="Built-in type editor"><h2>{kind} layout and settings</h2><p>Applies to this type throughout the project. Extend built-in records with typed fields stored under metadata.contentFields. Core canonical fields keep their existing domain rules. Removing or changing fields must remain compatible with existing records.</p><p role="status">{busy?'Loading…':message}</p>
{#if saved}<p>Settings revision {saved.revision}</p><fieldset disabled={busy}>
<label>Default GM context<select bind:value={context}><option value="searchable">Searchable</option><option value="partial">Partial</option><option value="pinned">Pinned</option></select></label><p>Records without an override inherit this preference. Pinned sends full authored fields; Partial sends title and description only; Searchable has no catalog preload.</p>
<label>Built-in field schema<textarea bind:value={fields} rows="8"></textarea></label><label>Built-in field defaults<textarea bind:value={defaults} rows="6"></textarea></label><label><input type="checkbox" bind:checked={migrateDefaults}/> Apply missing defaults to existing records</label><p>Defaults always apply to new records. Migrating existing records fills missing values only and requires a reviewed apply. Values can be text, longtext, number, boolean, enum, array or object.</p>
<label>Built-in layout<textarea bind:value={layout} rows="16"></textarea></label><p>Each section has a title and fields with a path and label. Available roots: {canonicalLayoutRoots[kind].join(', ')}. State, metadata and resources support dotted paths such as state.stats.hp.</p>
<div class="actions"><button onclick={()=>save(true)}>Preview built-in layout</button><button onclick={()=>save()} disabled={!dirty}>Save built-in type settings</button><button onclick={reload}>Discard and reload type</button><button disabled={dirty} onclick={()=>history()}>View type history</button></div>
{#if confirmation}<div role="alert"><p>Apply the reviewed {kind} type at revision {confirmation.expectedRevision}? {confirmation.migrationCount} records receive missing defaults. {#if !confirmation.definition.layout.length}The display layout will be empty.{/if} Existing values and canonical identities are retained.</p><button onclick={confirmClear}>Confirm type changes</button><button onclick={()=>confirmation=null}>Cancel type changes</button></div>{/if}
</fieldset>{#if impact}<p role="status">This type has {impact.total} visible records across project games; {impact.inherited} inherit its default. With the draft policy: {impact.pinned} Pinned, {impact.partial} Partial, about {impact.estimatedTokens.toLocaleString()} preload tokens before game, branch, and POV filtering.</p>{/if}{#if preview}<h3>Sample layout preview</h3><CanonicalLayout definition={preview} record={sample}/>{/if}
{#if revisions.length}<h3>Retained type history</h3><label><input type="checkbox" bind:checked={restoreMigrate} onchange={()=>restoreReview=null}/> Fill missing defaults when restoring a schema</label>{#each revisions as revision}<details><summary>Type revision {revision.revision} · {revision.reason}</summary><pre>{JSON.stringify(revision.definition,null,2)}</pre><button onclick={()=>previewRestore(revision.revision)} disabled={dirty||busy}>Preview restore</button></details>{/each}{#if older!==null}<button onclick={()=>history(true)} disabled={dirty||busy}>Older type revisions</button>{/if}{/if}
{#if restoreReview}<section role="alert"><h3>Restore type revision {restoreReview.targetRevision}?</h3><p>{restoreReview.migrationCount} existing records would receive missing defaults.</p>{#each restoreReview.changes as change}<details><summary>{change.field}</summary><pre>Current: {JSON.stringify(change.from,null,2)}
Restored: {JSON.stringify(change.to,null,2)}</pre></details>{/each}{#each restoreReview.conflicts as conflict}<p>{conflict.name}: {conflict.error}</p>{/each}<button onclick={applyRestore} disabled={dirty||busy||!restoreReview.compatible}>Confirm restore as new revision</button><button onclick={()=>restoreReview=null}>Cancel</button></section>{/if}{/if}</section>
<style>fieldset{border:0;padding:0;min-width:0}label{display:grid;gap:.3rem;margin:.7rem 0}textarea{width:100%;font:.85rem monospace}select,textarea,button{padding:.55rem .7rem;border:1px solid var(--border-primary);border-radius:.35rem;background:var(--bg-secondary);color:inherit;max-width:100%}button{cursor:pointer;font-size:.8rem}button:disabled{opacity:.5}.actions{display:flex;gap:.7rem;flex-wrap:wrap}p{font-size:.85rem;color:var(--text-secondary);margin:.6rem 0}h2,h3{margin:.8rem 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.8rem}summary{cursor:pointer;margin:.6rem 0}</style>
